const fs = require('node:fs');
const path = require('node:path');
const cwd = process.env.OPEN_SCIENCE_RUNTIME_DIR || process.cwd();
const handoff = process.env.OPEN_SCIENCE_HANDOFF_DIR;
const list = (dir) => {
  try { return fs.readdirSync(dir); } catch (e) { return e.message; }
};
console.log('cwd:', cwd);
console.log('cwd entries:', list(cwd));
console.log('handoff:', handoff);
console.log('handoff entries:', handoff ? list(handoff) : '(none)');

const fs = require('node:fs');
const cwd = process.env.OPEN_SCIENCE_RUNTIME_DIR || process.cwd();
console.log('cwd:', cwd);
// Find the inputs directory by searching for the file
const findInputs = (dir, depth=0) => {
  if (depth > 3) return [];
  const out = [];
  try {
    for (const name of fs.readdirSync(dir)) {
      if (name === 'inputs') {
        const p = require('node:path').join(dir, name);
        out.push({ p, listing: fs.readdirSync(p) });
      } else {
        const sub = require('node:path').join(dir, name);
        try {
          const st = fs.statSync(sub);
          if (st.isDirectory()) out.push(...findInputs(sub, depth+1));
        } catch {}
      }
    }
  } catch (e) {}
  return out;
};
console.log(JSON.stringify(findInputs(cwd), null, 2));

const fs = require('node:fs');
const path = require('node:path');
const dataRoot = '/tmp/notebook-fixture/project/session/data';
console.log('data root:', dataRoot);
console.log('listing:');
for (const e of fs.readdirSync(dataRoot)) {
  const st = fs.statSync(path.join(dataRoot, e));
  console.log(' -', e, st.isDirectory() ? '(dir)' : `(${st.size} bytes)`);
}
const inputs = path.join(dataRoot, 'inputs');
if (fs.existsSync(inputs)) {
  console.log('inputs/ entries:');
  for (const e of fs.readdirSync(inputs)) {
    const st = fs.statSync(path.join(inputs, e));
    console.log(' -', e, st.isDirectory() ? '(dir)' : `(${st.size} bytes)`);
  }
}
